exercises.solution:
import { createHmac, timingSafeEqual } from "node:crypto";

export function verifyWebhookSignature(
  rawBody: string,
  signatureHex: string,
  timestampSec: number,
  secret: string,
  maxDriftSec = 300
): boolean {
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - timestampSec) > maxDriftSec) return false;
  const expectedHash = createHmac("sha256", secret).update(`${timestampSec}.${rawBody}`).digest();
  const providedHash = Buffer.from(signatureHex, "hex");
  if (expectedHash.length !== providedHash.length) return false;
  return timingSafeEqual(expectedHash, providedHash);
}
